                tradeFor: "$35"
            }
        ];

        // 用户储物箱物品 - 使用定位符
        const inventoryItems = $36;

        // 初始化交易界面
        function initTradeInterface() {
            const traderItemsContainer = document.getElementById('traderItems');
            const inventoryContainer = document.getElementById('inventoryItems');

            // 生成交易者物品列表
            traderItemsContainer.innerHTML = '';
            traderItems.forEach((item, index) => {
                const itemElement = document.createElement('div');
                itemElement.className = 'trade-item';
                itemElement.innerHTML = `
                    <div class="item-name">名称: ${item.name}</div>
                    <div class="item-desc">介绍: ${item.desc}</div>
                    <div class="item-trade">交易物品: ${item.tradeFor}</div>
                    <button class="trade-button" onclick="initiateTrade(${index})">交易</button>
                `;
                traderItemsContainer.appendChild(itemElement);
            });

            // 生成用户储物箱
            inventoryContainer.innerHTML = '';
            inventoryItems.forEach(item => {
                const itemElement = document.createElement('div');
                itemElement.className = 'inventory-item';
                itemElement.innerHTML = `<div class="inventory-item-name">${item}</div>`;
                inventoryContainer.appendChild(itemElement);
            });
        }

