        function closeChatModal() {
            document.getElementById('chatModal').style.display = 'none';
        }

        // 发送聊天消息
        function sendChatMessage() {
            const message = document.getElementById('chatMessage').value.trim();
            if (message) {
                // 如果在SillyTavern环境中
                if (typeof triggerSlash === 'function') {
                    triggerSlash(`/send ${message}|/trigger`);
                } else {
                    console.log('向AI发送聊天消息:', message);
                    alert(`消息已发送: ${message}`);
                }
                closeChatModal();
            } else {
                alert('请输入消息内容');
            }
        }

        // 打开交易模态窗口
        function openTradeModal() {
            document.getElementById('tradeModal').style.display = 'flex';
            initTradeInterface();
        }

        // 关闭交易模态窗口
        function closeTradeModal() {
            document.getElementById('tradeModal').style.display = 'none';
        }

        // 发起交易
        function initiateTrade(itemIndex) {
            const item = traderItems[itemIndex];
            const tradeMessage = `用${item.tradeFor}交换${item.name}`;

            // 如果在SillyTavern环境中
            if (typeof triggerSlash === 'function') {
                triggerSlash(`/send ${tradeMessage}|/trigger`);
            } else {
                console.log('向AI发送交易请求:', tradeMessage);
                alert(`交易请求: ${tradeMessage}`);
            }
        }

        // 离开当前位置
        function leaveLocation() {
            const leaveMessage = "离开";

            // 如果在SillyTavern环境中
            if (typeof triggerSlash === 'function') {
                triggerSlash(`/send ${leaveMessage}|/trigger`);
            } else {
                console.log('向AI发送离开消息:', leaveMessage);
                alert(`离开请求: ${leaveMessage}`);
            }
        }

        // 点击模态窗口外部关闭
        window.addEventListener('click', function(event) {
            if (event.target.classList.contains('modal')) {
                closeChatModal();
                closeTradeModal();
            }
        });

        // 初始化
        document.addEventListener('DOMContentLoaded', function() {
            // 可以在这里添加初始化逻辑
        });
    </script>
