                const ash = document.createElement('div');
                ash.className = 'ash';

                const size = Math.random() * 5 + 1;
                const left = Math.random() * 100;
                const duration = Math.random() * 10 + 5;
                const delay = Math.random() * 5;

                ash.style.width = `${size}px`;
