                option.className = 'profession-option';
                option.innerHTML = `
                    <input type="radio" name="profession" value="${prof.id}" id="${prof.id}" class="profession-input">
                    <label for="${prof.id}" class="profession-label">
                        <div class="profession-name">${prof.name}</div>
                        <div class="profession-desc">${prof.desc}</div>
                        <div class="profession-items">${prof.items}</div>
                    </label>
                `;
                grid.appendChild(option);
            });
        }

        // 页面切换函数
        function showPage(pageId) {
            document.querySelectorAll('.page').forEach(page => {
                page.classList.remove('active');
            });
            document.getElementById(pageId).classList.add('active');
        }

        // 礼包兑换功能
        function redeemGift() {
            const giftCode = document.getElementById('giftCodeInput').value.trim();
            if (giftCode) {
                document.getElementById('giftCodeDisplay').textContent = giftCode;
                document.getElementById('giftInfo').style.display = 'block';
                document.getElementById('giftModal').style.display = 'none';
            } else {
                alert('请输入兑换码');
            }
        }

        // 开始游戏功能
        function startGame() {
            const name = document.getElementById('playerName').value.trim();
            const gender = document.querySelector('input[name="gender"]:checked');
            const profession = document.querySelector('input[name="profession"]:checked');
            const giftCode = document.getElementById('giftCodeDisplay').textContent;

            if (!name) {
                alert('请输入姓名');
                return;
            }

            if (!gender) {
                alert('请选择性别');
                return;
            }

            if (!profession) {
                alert('请选择职业');
                return;
            }

            const professionData = professions.find(p => p.id === profession.value);
            const message = `开始游戏: 姓名=${name}, 性别=${gender.value === 'male' ? '男性' : '女性'}, 职业=${professionData.name}, 礼包=${giftCode || '无'}`;

            // 如果在SillyTavern环境中
            if (typeof triggerSlash === 'function') {
                triggerSlash(`/send ${message}|/trigger`);
            } else {
                console.log('向AI发送开始游戏信息:', message);
                alert(`游戏开始: ${message}`);
            }
        }

        // 返回功能
        function goBack() {
            // 清除第2页数据
            document.getElementById('playerName').value = '';
            document.querySelectorAll('input[name="gender"]').forEach(input => input.checked = false);
            document.querySelectorAll('input[name="profession"]').forEach(input => input.checked = false);
            document.getElementById('giftInfo').style.display = 'none';
            document.getElementById('giftCodeDisplay').textContent = '';

            showPage('page1');
        }

        // 初始化事件监听
        document.addEventListener('DOMContentLoaded', function() {
            initProfessions();

            // 开始按钮
            document.getElementById('startButton').addEventListener('click', function() {
                showPage('page2');
            });

            // 礼包图标
            document.getElementById('giftIcon').addEventListener('click', function() {
                document.getElementById('giftModal').style.display = 'flex';
                document.getElementById('giftCodeInput').value = '';
            });

            // 返回箭头
            document.getElementById('backArrow').addEventListener('click', goBack);

            // 开始游戏按钮
            document.getElementById('startGameButton').addEventListener('click', startGame);

            // 礼包模态窗口按钮
            document.getElementById('confirmGift').addEventListener('click', redeemGift);
            document.getElementById('cancelGift').addEventListener('click', function() {
                document.getElementById('giftModal').style.display = 'none';
            });

            // 点击模态窗口外部关闭
            window.addEventListener('click', function(event) {
                if (event.target === document.getElementById('giftModal')) {
                    document.getElementById('giftModal').style.display = 'none';
                }
            });
        });
    </script>
</body>
</html>
