        let currentLocation = null;

        function openLocationModal(locationId) {
            const location = locations[locationId];
            if (!location) return;

            currentLocation = locationId;

            document.getElementById('modalLocationName').textContent = location.name;
            document.getElementById('modalLocationDesc').textContent = location.description;
            document.getElementById('modalLocationResources').textContent = location.resources;
            document.getElementById('modalLocationRisks').textContent = location.risks;

            document.getElementById('modalLocationTime').textContent = `单程时间: ${location.travelTime}小时`;

            const imageElement = document.getElementById('modalLocationImage');
            if (location.imageUrl) {
                imageElement.src = location.imageUrl;
                imageElement.style.display = 'block';
            } else {
                imageElement.style.display = 'none';
            }

            document.getElementById('locationModal').style.display = 'flex';
        }

        function closeLocationModal() {
            document.getElementById('locationModal').style.display = 'none';
            currentLocation = null;
        }

        function goToLocation() {
            if (!currentLocation) return;

            const location = locations[currentLocation];
            const message = `前往${location.name}`;

            if (typeof triggerSlash === 'function') {
                triggerSlash(`/send ${message}|/trigger`);
            } else {
                console.log('向AI发送:', message);
                alert(`准备前往: ${location.name}`);
            }

            closeLocationModal();
        }

        document.addEventListener('DOMContentLoaded', function() {
            const markers = document.querySelectorAll('.location-marker');
            markers.forEach(marker => {
                marker.addEventListener('click', function() {
                    const locationId = this.getAttribute('data-location');
                    openLocationModal(locationId);
                });
            });

            window.addEventListener('click', function(event) {
                const modal = document.getElementById('locationModal');
                if (event.target === modal) {
                    closeLocationModal();
                }
            });
        });
    </script>
