        // 创建细菌污染效果
        function createContamination() {
            const roomAreas = document.querySelectorAll('.room-area');
            roomAreas.forEach(area => {
                if (Math.random() > 0.5) {
                    const cont = document.createElement('div');
                    cont.className = 'contamination';

                    const size = 30 + Math.random() * 70;
                    cont.style.width = `${size}px`;
                    cont.style.height = `${size}px`;
                    cont.style.left = `${Math.random() * 80}%`;
                    cont.style.top = `${Math.random() * 80}%`;
                    cont.style.animationDelay = `${Math.random() * 5}s`;

                    area.appendChild(cont);
                }
            });
        }

