        .ending-title {
            text-align: center;
            font-size: 48px;
            font-weight: bold;
            color: #8b0000;
            text-shadow: 
                0 0 20px rgba(139, 0, 0, 0.7),
                0 2px 4px rgba(0, 0, 0, 0.8);
            padding: 30px 20px;
            background: 
                linear-gradient(to right, 
                    rgba(139, 0, 0, 0.2) 0%, 
                    rgba(100, 0, 0, 0.4) 50%, 
                    rgba(139, 0, 0, 0.2) 100%);
            border-bottom: 3px solid #8b0000;
            position: relative;
        }

        .ending-title::after {
            content: "";
            position: absolute;
            bottom: 0;
            left: 0;
            width: 100%;
            height: 1px;
            background: linear-gradient(to right, transparent, #8b0000, transparent);
            animation: title-glow 3s ease-in-out infinite;
        }

        @keyframes title-glow {
            0%, 100% { 
                box-shadow: 0 0 10px rgba(139, 0, 0, 0.5);
