            width: 100%;
            height: 350px;
            background: #000;
            border-bottom: 2px solid #333;
            overflow: hidden;
            position: relative;
        }

        .image-section::before {
            content: "";
            position: absolute;
            top: 0;
            left: 0;
            width: 100%;
            height: 100%;
            background: 
                linear-gradient(45deg, transparent 48%, rgba(139, 0, 0, 0.2) 50%, transparent 52%);
            background-size: 20px 20px;
            animation: scan 8s linear infinite;
            pointer-events: none;
            z-index: 2;
        }

        @keyframes scan {
            0% { transform: translateY(-100%); }
            100% { transform: translateY(100%); }
        }

        .ending-image {
            width: 100%;
            height: 100%;
            object-fit: cover;
            filter: grayscale(0.8) contrast(1.3) brightness(0.6) sepia(0.3);
        }

