            min-height: 150px;
            line-height: 1.8;
            font-size: 16px;
            color: #aaa;
            position: relative;
            z-index: 1;
            overflow-wrap: break-word;
            word-wrap: break-word;
        }

        .message-area::before {
            content: "";
            position: absolute;
            top: 0;
            left: 0;
            width: 100%;
            height: 100%;
            background: 
                repeating-linear-gradient(0deg, 
                    transparent 0px, 
                    transparent 1px, 
                    rgba(139, 0, 0, 0.1) 1px, 
                    rgba(139, 0, 0, 0.1) 2px);
            pointer-events: none;
        }

        .score-section {
