            <div class="form-group">
                <label class="form-label">选择职业</label>
                <div class="profession-grid" id="professionGrid">
                    <!-- 职业选项将通过JavaScript动态生成 -->
                </div>
            </div>

            <div class="gift-info" id="giftInfo" style="display: none;">
                <div class="gift-title">兑换礼包信息</div>
                <div class="gift-code" id="giftCodeDisplay"></div>
            </div>

            <button class="start-game-btn" id="startGameButton">开始游戏</button>
        </div>
