    <!-- 礼包兑换模态窗口 -->
    <div class="modal" id="giftModal">
        <div class="modal-content">
            <div class="modal-title">兑换礼包</div>
            <input type="text" class="modal-input" id="giftCodeInput" placeholder="输入兑换码">
            <div class="modal-buttons">
                <button class="modal-btn modal-cancel" id="cancelGift">取消</button>
                <button class="modal-btn modal-confirm" id="confirmGift">确认兑换</button>
            </div>
        </div>
